
/* Event views show a shareable /e/<slug>/ address (a real page with its own title, description and cover, so WhatsApp/LinkedIn previews work).
   APP_PATH is where this app lives; hash-only URLs and bare-path URLs always resolve against it, never against /e/<slug>/. */
const APP_PATH=/^\/e\//.test(location.pathname)?"/":location.pathname;
(function(){["pushState","replaceState"].forEach(m=>{const o=history[m];history[m]=function(st,t,u){if(typeof u==="string"&&u.charAt(0)==="#")u=APP_PATH+location.search+u;return o.call(this,st,t,u);};});})();
