function sectorsFor(e){const a=SECTORS.filter(c=>SEC_RE[c].test(e.title));(e.xsectors||[]).forEach(c=>{if(SECTORS.includes(c)&&!a.includes(c))a.unshift(c);});return a;}
function tp(id,opts,max,sel,ph){const root=document.getElementById(id);if(!root)return;let chosen=(sel||[]).filter(x=>opts.includes(x)).slice(0,max);
  root.classList.add("tp");root.innerHTML=`<div class="tpbox"></div><ul class="tplist" hidden></ul><div class="tpnote"></div>`;
  const box=root.querySelector(".tpbox"),list=root.querySelector(".tplist"),note=root.querySelector(".tpnote");let inp;
  const draw=()=>{box.innerHTML=chosen.map(v=>`<span class="tpchip" data-v="${esc(v)}">${esc(v)}<button type="button" aria-label="Remove ${esc(v)}">×</button></span>`).join("")+(chosen.length<max?`<input class="tpin" type="text" autocomplete="off" placeholder="${chosen.length?"Add another…":ph}">`:"");
    inp=box.querySelector(".tpin");note.textContent=chosen.length>=max?`Maximum of ${max} reached. Remove one to change it.`:`Up to ${max}. Type to search.`;
    box.querySelectorAll(".tpchip button").forEach(b=>b.onclick=()=>{chosen=chosen.filter(x=>x!==b.parentElement.dataset.v);draw();});
    if(inp){inp.oninput=sug;inp.onfocus=sug;inp.onblur=()=>setTimeout(()=>list.hidden=true,150);inp.onkeydown=ev=>{if(ev.key==="Enter"){ev.preventDefault();const f=list.querySelector("li[data-v]");if(f)add(f.dataset.v);}if(ev.key==="Backspace"&&!inp.value&&chosen.length){chosen.pop();draw();}};}};
  const add=v=>{if(chosen.length<max&&!chosen.includes(v)){chosen.push(v);}draw();if(inp)inp.focus();};
  const sug=()=>{const q=(inp.value||"").trim().toLowerCase(),m=opts.filter(o=>!chosen.includes(o)&&(!q||o.toLowerCase().includes(q))).slice(0,8);
    list.innerHTML=m.map(o=>`<li data-v="${esc(o)}">${esc(o)}</li>`).join("")||`<li class="none">No match</li>`;list.hidden=false;
    list.querySelectorAll("li[data-v]").forEach(li=>li.onmousedown=ev=>{ev.preventDefault();add(li.dataset.v);});};
  draw();}
const picked=id=>[...document.querySelectorAll("#"+id+" .tpchip")].map(x=>x.dataset.v);
function catsFor(e){const a=CAT_TYPES.filter(c=>CAT_RE[c].test(c==="Women in Tech"?e.title+" "+(e.host||""):e.title));(e.xcats||[]).forEach(c=>{if(CAT_TYPES.includes(c)&&!a.includes(c))a.push(c);});return a;}
