{const seen=new Set(EVENTS.map(e=>(e.link||"").split("?")[0].replace(/\/$/,"").toLowerCase()));
 [...MORE,...MORE2,...BAKED_EVENTS].forEach(([hub,date,start,end,title,link,venue,host],i)=>{const key=link.toLowerCase();if(seen.has(key))return;seen.add(key);
   const ys=/yorkseed/i.test(title);EVENTS.push({id:"m"+i,title,hub,date,start,end,type:inferType(title),host,tags:inferTags(title),aud:[],place:ys?"spotlight":null,week:(WEEKS.find(w=>w.hub===hub&&date>=w.start&&date<=w.end&&(w.re.test(title)||w.id==="lisws"||w.id==="slush"||w.id==="switch"))||{}).id||null,img:"ev"+(1+i%8),venue:venue||"Location after RSVP",link,desc:"Details and registration on the event page."});});}
{const sf=EVENTS.find(e=>/luma\.com\/vc-hack-nyc/.test(e.link||""));if(sf){sf.place="featured";sf.sample=true;}}
{const intro=EVENTS.find(e=>e.link==="https://luma.com/lv9l1t41");if(intro){intro.start="17:00";intro.end="19:30";intro.venue="New York, NY";intro.type="Investor Events";}}
// Cities added through submissions: a new city opens once its first event is accepted.
function makeHub(name,country,tz){const id="c-"+name.toLowerCase().normalize("NFD").replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"");return{id,name,country:country||"",tz,img:"",code:name.replace(/[^A-Za-z]/g,"").slice(0,3).toUpperCase(),lede:`Founder, investor and venture events in ${name}.`,isNew:true};}
try{const nh=JSON.parse(localStorage.getItem("yl-newhubs")||"[]");if(Array.isArray(nh))nh.forEach(h=>{if(h&&h.id&&!HUBS.some(x=>x.id===h.id))HUBS.push(h);});}catch(e){}
try{const s=JSON.parse(localStorage.getItem("yl-subs2")||"[]");if(Array.isArray(s))EVENTS=EVENTS.concat(s.filter(e=>HUBS.some(h=>h.id===e.hub)));}catch(e){}
let saved=new Set();try{saved=new Set(JSON.parse(localStorage.getItem("yl-saved")||"[]"));}catch(e){}
function decorate(e){const tz=hubById(e.hub).tz;e.noTime=!e.start;e.utc=toUtc(e.date,e.start||"12:00",tz);e.utcEnd=toUtc(e.date,e.end||"23:59",tz);e.cats=catsFor(e);e.sectors=sectorsFor(e);return e;}
function fE(e,tz){return e.noTime?"":fT(e.utc,tz)}
function fEnd(e,tz){return e.noTime?"":fT(e.utcEnd,tz)}
function abE(e,tz){return e.noTime?"":abbr(e.utc,tz)}
const DESC={"https://luma.com/9o4tb0f1": "A startup innovation forum during Taiwan Weeks at Grand Hilai Taipei in Nangang, hosted by SparkLabs Taiwan. Founders, investors and corporate partners hear talks and panels on Taiwan's startup ecosystem and cross-border growth.", "https://luma.com/8e2vn5zl": "A hands-on afternoon workshop on building trading tools with AI and vibe coding, hosted by Gaea Ventures and Logan Chen. For builders and founders curious about AI-assisted development; taught in Mandarin.", "https://luma.com/mo58jljq": "A practical first class in making short-form video with AI, for freelancers, shop owners and creators. Hosted by AI Project Ark; taught in Mandarin.","https://luma.com/lv9l1t41": "An invitation-only evening in New York for a curated mix of founders, investors and ecosystem leaders, ahead of Web Summit. Tickets are by role and need approval, with a small confirmation fee. Hosted by Yorkseed's Jessica Sophia Wong and Kimberly Neer.", "https://luma.com/vc-hack-nyc": "A one-day hackathon at Betaworks where teams of four build software for venture problems: sourcing, diligence, portfolio support and LP reporting. Hosted by localhost:nyc and VCLab for founders, engineers and builders, with VCs judging live demos. Registration needs host approval.", "https://luma.com/jkkkhcbt": "Startups pitch mental health ideas to investors and healthcare decision-makers on Zoom, and the audience votes each one hot or not. Part of the Yorkseed Expert Series with Health Board Advisors, hosted by Sabrina Runbeck, Val Torres and Jessica Sophia Wong. Open to clinicians, researchers, benefits leaders and investors.", "https://luma.com/2lalacnc": "A virtual roundtable for investors and healthcare leaders on women's health: menopause, fertility and AI-driven preventive care. Part of the Yorkseed Expert Series with Health Board Advisors, hosted by Sabrina Runbeck, Jessica Sophia Wong and Val Torres. For accredited investors, VCs, fund managers and health executives; registration needs approval.", "https://luma.com/44qkfxdu": "Yorkseed's opening-night party for Web Summit Lisbon: a networking soirée for founders, investors and partners, hosted by founder Jessica Sophia Wong. General, VIP and founder or investor tiers, some by approval. The All-Access Week Pass covers most Yorkseed events that week.", "https://luma.com/a2jp6jc9": "Yorkseed's pop-up home base in Lisbon, open all week Nov 9–13 during Web Summit: coworking, meeting rooms and a restaurant discount, plus curated events including an opening reception with Pitch Roulette, a Capital Table Lunch, founder and investor meetups, community breakfasts and VC office hours. Hosted by Jessica Sophia Wong. Founder, investor and general tiers; RSVP on Luma first, and the address is shared after registration.", "https://luma.com/ryyphlgu": "A seated, curated lunch during Web Summit Lisbon for founders, executives, investors and ecosystem builders. Guests get seated introductions and personal connection picks. Hosted by Jessica Sophia Wong; most tiers need approval.", "https://luma.com/lj25z4k3": "A curated seated lunch in Lisbon during Web Summit that puts founders, investors and ecosystem leaders at one table for real conversation, not pitching. Hosted by Yorkseed founder Jessica Sophia Wong. Every tier needs approval.", "https://luma.com/hox2a889": "A salon for founders and investors working across borders, part of the Yorkseed Passport Series at Web Summit Lisbon. Hosted by Yorkseed founder Jessica Sophia Wong. The venue is shared with registered guests.", "https://luma.com/jmjk0qqh": "A seated lunch for founders, investors, fund managers, family offices and corporate leaders during Web Summit Lisbon. Structured introductions and relationship-first conversation, with no stage or panels. Part of the Yorkseed Passport Series; approval required.", "https://luma.com/k0zamjmi": "A private evening during Web Summit week for about 45 selected family offices, LPs, GPs, institutional investors and private investors. Conversation-first, with no stage or panels. Hosted by Valois by Yorkseed; attendance by application or invitation.", "https://luma.com/i7llsb2c": "The closing gathering of the Yorkseed Passport Series at Web Summit Lisbon, bringing founders and investors from the week together one last time. Hosted by Yorkseed founder and CEO Jessica Sophia Wong.", "https://luma.com/circle-day-2026-in-person": "An in-person day at Squarespace's New York headquarters for professional web designers and agencies. Squarespace Circle brings together leading creators and previews what's next for the platform. Registration is waitlisted.", "https://luma.com/7ndhdy7n": "A free three-day build sprint for pre-seed founders at SAP Labs in Palo Alto. Judges from Stanford, Nvidia, Meta and Microsoft AI watch teams build, then question them on their decisions. Hosted by Mark Evans and Sahar Mor; registration needs approval.", "https://luma.com/31kdbtga": "A short session on answer engine optimization, AI marketing and the Profound platform, held the day before Zero Click London at the InterContinental O2. Hosted by Profound's community team; registration needs approval.", "https://luma.com/attio-ramp": "An evening for founders and operators taking companies beyond founder-led sales, presented by Attio and Ramp. A panel with James Allgrove, Alexander Christie and Eric Oancea, then food, drinks and networking. Registration needs approval.", "https://luma.com/7fudgbbj": "Pre-seed to Series A startups get pre-matched, eight-minute 1:1 meetings with investors. Organized by The Startup Station with Pearl Cohen as sponsor and host. Founders apply; selected founders pay an admission fee.", "https://luma.com/3tto5407": "A free, invite-only applied AI summit on the future of finance at The Times Center, presented by Monk. About 150 CFOs, operators, founders and researchers, with speakers from AI-native firms and large enterprises. Attendance by application.", "https://luma.com/mrkdgmp5": "Startup Grind NYC's live demo night at The Yard in Herald Square. Each startup gets six minutes to pitch and demo working product, then four minutes of audience questions. $5 tickets; startups apply to present.", "https://luma.com/08f1p0h0": "Ambrook's Ali Aas and Jesse Hirsch show how they design a print newspaper in Figma with Claude, from setup to press-ready files. Q&A and drinks follow, 21+. Registration needs approval.", "https://luma.com/4oxpumv5": "Visiting Singapore medtech startups pitch to Boston healthcare leaders at CIC Cambridge, followed by a networking reception. Hosted by Enterprise Singapore and MedTech Catapult. Advance registration and photo ID required; currently waitlisted.", "https://luma.com/corginyc-ervo": "An evening at Corgi Cafe for founders, operators and real estate people. Drinks, then a founder-led talk on scaling teams and offices in person, with CBRE on leases. Registration needs approval.", "https://luma.com/zfdohi1w": "A hands-on NY App Week workshop for consumer app founders and growth leads planning a creator content program with healthy margins. Participants map out costs, creator rates and formats. Hosted by Sophia Vinasco and scale v; registration needs approval.", "https://luma.com/8fobi9xw": "The first of a quarterly series on care robots that take on repetitive clinical tasks under staff supervision. Keynotes, a panel and demos, with speakers from Norbert Health and Wandercraft. For operators, clinicians, roboticists, payers, regulators and investors; currently waitlisted.", "https://luma.com/trae-stephens-spc": "A fireside chat with Trae Stephens, Founders Fund general partner and Anduril co-founder, at South Park Commons. Doors open early for mingling. For founders, researchers and technologists in the SPC community; registration needs approval.", "https://luma.com/yshtx07x": "A private screening of A24's documentary on Theranos founder Elizabeth Holmes, hosted by Concentrate AI and RRE Ventures. For AI founders, CTOs, engineers and builders. Request to join; approval required.", "https://luma.com/durable-ai-october": "A meetup on keeping long-running AI agents reliable: surviving crashes, acting on outside systems and staying observable. Talks and demos from Temporal, Kernel and Oodle.ai, then a panel and networking. For engineers running agents in production; approval required.", "https://luma.com/plain-sentry": "An evening at Sentry's SF office on how AI agents, MCP and APIs are changing support engineering. Speakers from Sentry and Plain, audience Q&A and open discussion. For support and customer-facing engineers; approval required.", "https://luma.com/dj22bayb": "Dinner at Stanford with two short talks on colorectal cancer biology and AI virtual cell models, by Ganesh Pusapati and Angela Oliveira Pisco. For researchers, computational biologists and drug discovery teams. Hosted by The Frontier Syndicate; approval required.", "https://luma.com/ddz6vkfs": "A free open-source happy hour at Cloudflare's SF office before func(tion) at Oracle Park, with drinks, food and a DJ. Intros from Evan You, Fred Schott, Ryan Dahl, Bert Belder and others. Free; currently full.", "https://luma.com/bfgu761e": "An OSS Week evening at Hogpatch for founders, maintainers and engineers building with open-source AI tools. Speakers from PostHog, Cline, Unikraft and other open-source startups lead short round-table talks, then drinks. Hosted by PostHog and 1984 Ventures; rolling approval.", "https://luma.com/mupawovc": "Bioptimus CEO Jean-Philippe Vert presents M-Optimus, a biology world model that combines histology, single-cell and spatial data. A demo, Q&A, food and drinks. Hosted by Bits in Bio SF and MBC BioLabs; currently waitlisted.", "https://luma.com/cc7vxzrr": "A casual bar meetup where engineers from recent Y Combinator batches trade notes on stacks, infrastructure and architecture tradeoffs. Hosted by Infisical and Mintlify, with drinks on them. 21+; approval required.", "https://luma.com/tsdd-26": "RevenueCat's Shipaton winners demo their apps under the Times Square billboards. Drop in through the day, try the apps and vote for a People's Choice winner. Part of NY App Week; free with registration.", "https://luma.com/43oort49": "A casual morning design lab during NY App Week: bring an app or prototype and get quick design, product and UX feedback over coffee and breakfast. Hosted by Lickability's Thomas DeVuono; currently waitlisted.", "https://luma.com/agentcon-us": "A two-day Linux Foundation conference in San Jose on open agentic AI: agent architectures, infrastructure and interoperability protocols like MCP. Speakers from Anthropic, Google and AWS, for engineers running agents in production. Paid tickets.", "https://luma.com/gkmdzbk9": "How agentic AI moves from pilot to production in financial services and insurance. Two panels with leaders from Monzo, Checkout.com, S&P Global, Aventum, Nettle and Brit Insurance, at IFX Payments' London office. For founders, operators and investors; approval required.", "https://luma.com/5luq6uxf": "An industry evening at Central Saint Martins on how physical experiences can hold attention in a digital age. A panel chaired by Yasmin Jones-Henry, then Q&A and an exhibition viewing. Free with registration.", "https://luma.com/l1z4azjp": "Fuckup Nights, where people share business failures, teams up with Acquisition Entrepreneurs, a community for buying and running existing companies. Two fireside chats with Carl Lundberg and Vitten Varma. £5 entry.", "https://luma.com/k479y31u": "A free evening from Intruder with short talks on AI penetration testing and continuous security, then networking and a prize raffle. For cybersecurity, IT and DevOps professionals, 18+. Approval required.", "https://luma.com/granola-raspberry-pi": "Granola hosts Raspberry Pi co-founder and CEO Eben Upton in London to talk through the early ideas behind the company. Drinks and snacks before the 6pm start; doors close once it begins. Currently waitlisted.", "https://luma.com/m8q7l68w": "A free panel at Curve Club where European founders share lessons from doing business in Japan, and the Tokyo Metropolitan Government presents its startup programs, including SusHi Tech Tokyo. Run with London Venture Capital Network for startups, investors, accelerators and corporate innovation teams. Approval required.", "https://luma.com/eveur09a": "An evening hackathon for community engineers, DevRels and organizers to build community tools with Grok Bot and Cursor. Solo or teams of up to five ship working demos; the top five present in three-minute slots. Currently waitlisted.", "https://luma.com/wuiwb5fg": "A free afternoon in Cambridge connecting US-based AI founders from Greater China with Boston investors and tech leaders. An investor panel, selected startup pitches and open networking. Hosted by Boston Venture Connect; startups apply to present.", "https://luma.com/06hgn26s": "A morning masterclass from Asapty and RevenueCat that walks through a real client case linking Apple Ads spend and ROAS to subscription and paywall data. For UA managers, growth leads and subscription app founders, with coffee and pastries. Part of NY App Week; approval required.", "https://luma.com/1m5f9u8n": "A student trek to Flagship Pioneering's Cambridge headquarters, where the team that builds new biotech companies explains how AI fits into its work. For students registering with a .edu email; approval required.", "https://luma.com/buildp-ncun": "A half-day seminar of technical talks and panels on emerging open-source AI research, with speakers including Peter Norvig and Illia Polosukhin. Hosted by BuildPlanet with the Open Intelligence Foundation and NEAR AI. Approval required.", "https://luma.com/s6k8kdkh": "A technical evening at Pillar VC where Vercel and Jellyfish engineers demo agent architecture and introduce Eve, a new agent framework. Live demo, Q&A and hands-on building time for engineers working on AI agents. Approval required.", "https://luma.com/hhl725g4": "A casual recurring meetup at Harlem Tavern for people in nanotech, semiconductors, biotech and deep tech: researchers, engineers, founders, students and the curious. No talks or agenda, just conversation. Organized by Nanotech NYC; free.", "https://luma.com/gjw3js1t": "An invite-only Brooklyn evening for mobile app and game founders: drinks and frank talk about growing consumer apps. Part of NY App Week; approval required.", "https://luma.com/v63nd8d9": "An interactive NY App Week evening where founders, marketers and developers vote on real app growth experiments, debate industry tradeoffs and watch audience apps get roasted live. Drinks served. Hosted by Apptuitive; approval required.", "https://luma.com/fonzinyc-va2l": "A Halloween party at Fonzi's Williamsburg office for NYC engineers, founders and friends: costumes, drinks, games, music and fortune telling. Hosted by Fonzi, sponsored by Menlo Ventures. Approval required.", "https://luma.com/s8gi4oqd": "A Halloween networking happy hour in San Carlos for early-stage biotech founders, builders, investors and industry experts. A fireside chat and Q&A, then drinks, food and a costume contest. Co-hosted by Twist Bioscience, MBC BioLabs and others; approval required.", "https://luma.com/12t5e4lc": "StepFun launches its open-weights Step 5 Preview model for developers, founders and investors, co-hosted with Together AI. A model walkthrough, a panel with Pear VC, Cline and Harvey, live Q&A and networking. Approval required.", "https://luma.com/beta-79jb": "A one-day hackathon at the AWS Builder Loft where builders, researchers, founders and investors build multimodal products using models from AWS and OpenAI. Teams of two to four must ship a working demo. Hosted by Beta University; approval required.", "https://luma.com/z1h24dqe": "A research forum for people working where neural networks, program synthesis and formal reasoning meet. With François Chollet, Mike Knoop and the ARC Prize Foundation team, hosted by Greg Kamradt. Approval required.", "https://luma.com/pqlvj80n": "A Shabbat dinner for NYC founders, investors and engineers near Union Square: check-in, candle lighting, kiddush and a shared meal. Hosted by Tech Tribe. Standard and approval-only tickets.", "https://luma.com/a5yfh2ve": "A one-day buildathon at The Building Centre where builders of any AI skill level create plug-ins with early access to Lightfern's Mac app. Led by Lightfern and Bond AI, with talks from Jumpstart and Round Treasury. Approval required.", "https://luma.com/xrpl-hackathon-nyc": "A 36-hour weekend hackathon for developers, product people and finance-minded builders shipping products on the XRP Ledger. Hosted by XRPL Commons with Ripple, the XRPL Foundation and Mastercard, whose mentors and judges guide teams.", "https://luma.com/q5v9a6ak": "A weekend build event at Y Combinator's SF office where 175 selected builders use AI to ship products, with YC and partners judging. Open by application to pre-company founders, designers and non-engineers with two or more years of experience.", "https://luma.com/59t8euck": "A weekend hackathon where engineers, designers and non-technical builders take on nonprofit challenges in climate, mental health, justice and the arts. Run by Hack for Social Impact with the UN Convention to Combat Desertification and local nonprofits, with $5,000 in prizes. Approval required.", "https://luma.com/8pqcqqu0": "An AI film festival at Village East by Angelika with screenings, awards and industry networking for filmmakers, technologists and brands. Hosted by Harvard XR and SOHO International Film Festival, with jurors including Fred Grinstein and GMUNK. Pay what you want.", "https://luma.com/ziwf0ki0": "A one-day summit in Somerville on physical AI, nanotech and climate tech for startups, researchers, investors and industry. Hosted by Campus Deep Tech and MassVentures with SOSV and Engine Ventures, with speakers from MIT, Tufts, GM and NVIDIA. Approval required.", "https://luma.com/f0sstqgy": "A Tough Tech Week afternoon with a fireside chat featuring Phoenix Tailings CTO and co-founder Tomás Villalón Jr. on reshoring rare earths, plus a startup showcase and networking. For investors, LPs, founders and operators. Hosted by ven^x; approval required.", "https://luma.com/i5pzwtrz": "Early-stage biotech founders pitch rapid-fire to VC judges from Lilly Ventures, 5AM Ventures and Curie.Bio Breakout Fund, then network over drinks. Hosted by Mackenzie Scurka and Kristen Craft. Approval required.", "https://luma.com/toughtech-6pg5": "The opening night of Tough Tech Week: a networking evening at 255 State St for founders, investors and the wider tough tech community, with drinks and light bites. Hosted by Wolf & Company and Foley Hoag; approval required.", "https://luma.com/oga68g30": "A session on VC and PE funding for international founders scaling in New York, with Dan Jaeck of Crane VC and Joel Goschalk of Dundon Advisers on funding, expansion and exits. Hosted by Brits in Tech with Transatlantic Innovation Hub and The Knowledge Shop. Approval required.", "https://luma.com/jzkyiiz8": "A fireside chat at Fintech House on crypto becoming financial infrastructure, with speakers from Lagoon Finance, Round Treasury and Fireblocks, then Q&A and drinks. Hosted by Lisbon Ethereum Hub with Gnosis. Free; approval required.", "https://luma.com/xvf603kz": "A free screening of The Thinking Game, the documentary on Demis Hassabis and DeepMind's pursuit of AGI, at Good Company Books, followed by a group discussion. Organized by the Lisbon AI Safety Hub. Free with registration.", "https://luma.com/n82779zo": "Climate Circle Lisbon's monthly mixer at O Purista in Chiado: casual drinks and networking for the city's international climate and sustainability community. Free with registration.", "https://www.dtrsociety.org/digitas2026/": "An international conference on digitalization and smart solutions, running in person and online from November 1 to 5, just before Web Summit.", "https://informaconnect.com/pharma-forum-emea/": "Informa's forum for pharma meeting and congress strategy across Europe, the Middle East and Africa. For healthcare and life sciences professionals who plan and run medical events.", "https://www.b6gs.com/agenda": "The pre-event program for the B6G Summit on 6G, AI-RAN, physical AI and telecom infrastructure, with an exhibition and welcome reception. The main program runs November 4–5.", "https://www.meetup.com/strive-networking/events/315013485/": "A Strive Networking evening across industries for consultants, bankers, software engineers, entrepreneurs and other professionals. Tickets through Eventbrite.", "https://www.eventbrite.com/e/blockchain-and-business-networking-elevating-your-potential-lisbon-tickets-1990652525290": "A Strive Networking evening focused on blockchain alongside other industries, for investors, entrepreneurs, engineers, consultants and finance and tech professionals. 18+; ticketed.", "https://www.eventbrite.com/e/engineering-and-business-networking-elevating-your-potential-lisbon-tickets-1990652508239": "A Strive Networking evening focused on engineering alongside other industries, for engineers and business professionals. 18+; register on Eventbrite.", "https://www.eventbrite.com/e/tech-and-business-networking-elevating-your-potential-lisbon-tickets-1990652507236": "A Strive Networking evening focused on tech alongside other industries, for founders, engineers and business professionals. 18+; register on Eventbrite.", "https://www.eventbrite.com/e/dinner-with-entrepreneurs-monthly-lisbon-tickets-1983278468287": "A monthly dinner for Lisbon's founders and business community, built around peer connections and collaboration. Register on Eventbrite.", "https://www.globalcitizensolutions.com/event/wealth-migration-summit-2026/": "A private two-day summit from Global Citizen Solutions for investors, family offices, fund and wealth managers, advisors and government officials. Topics include cross-border wealth planning, investment migration, succession and global capital. Capped at 200 delegates.", "https://www.eventbrite.pt/e/understand-tickets-2001394083580": "An in-person session at Nova SBE on what generative AI is changing in higher education, with sociologist Mark Carrigan. Hosted by the school's Teaching Excellence & Innovation Center.", "https://iums2026.com/networking-events/": "An evening at the Academy of Sciences of Lisbon for the scientific and academic community, part of the IUMS 2026 congress. €60, or €45 for students.", "https://events.eurodefense.tech/events/european-defense-tech-hackathon-lisbon": "A weekend hackathon for 200+ builders working on dual-use and defence innovation, with public sector, investors and operators in the room. Runs November 6–8."};
/* continuous events: listed on every day from their date through UNTIL[link] (first day keeps its Yorkseed star) */
const UNTIL={"https://luma.com/a2jp6jc9":"2026-11-13"};
/* multi-day events (e.until = last day, YYYY-MM-DD): the first day is the real entry; each later day gets a copy
   (cont) so the event shows on every day it runs. Capped at 21 days so a months-long exhibition doesn't flood the List. */

function expandMulti(){let n=0;EVENTS.forEach(e=>{if(!e.until&&e.link&&UNTIL[e.link])e.until=UNTIL[e.link];});
  const have=new Set(EVENTS.map(x=>(x.link||x.title)+"|"+x.date));
  EVENTS.filter(e=>e.until&&e.until>e.date&&!e.cont).forEach(e=>{let k=0;for(let d=nextDay(e.date);d<=e.until&&k<21;d=nextDay(d),k++){const key=(e.link||e.title)+"|"+d;if(have.has(key))continue;have.add(key);EVENTS.push(decorate({...e,id:e.id+"_"+d,date:d,d0:e.date,place:null,cont:true}));n++;}});return n;}
expandMulti();
EVENTS.forEach(e=>{if(e.link&&DESC[e.link])e.desc=DESC[e.link];});
EVENTS.forEach(decorate);
const NOW=Date.now();
/* the same event often arrives from several sources (curated list, Luma, Eventbrite, a partner site): show it once */
let UP_KEY="",UP_VAL=[];
function dedupeEvents(list){const nk=t=>String(t||"").toLowerCase().normalize("NFKD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-z0-9]/g,"");
  const score=e=>(e.place?4:0)+(e.host?2:0)+(/luma\.com|lu\.ma|eventbrite/.test(e.link||"")?1:0)+(e.start?1:0)+(e.cover||e.img&&!/^ev\d/.test(e.img)?1:0);
  const mn=t=>{const p=String(t).split(":");return (+p[0])*60+(+p[1]||0);};
  const by={};const out=[];
  list.forEach(e=>{const k=e.hub+"|"+e.date,n=nk(e.title),arr=by[k]||(by[k]=[]);
    const m=arr.find(x=>(x.n===n||(Math.min(x.n.length,n.length)>=18&&(x.n.startsWith(n)||n.startsWith(x.n))))&&(!x.e.start||!e.start||Math.abs(mn(x.e.start)-mn(e.start))<=90));
    if(!m){arr.push({n,e});out.push(e);return;}
    const a=m.e,b=e,win=score(b)>score(a)?b:a,lose=win===a?b:a;
    ["host","venue","cover","desc","start","end"].forEach(f=>{if(!win[f]&&lose[f])win[f]=lose[f];});
    if(win!==a){out[out.indexOf(a)]=win;m.e=win;}});
  return out;}
const upcoming=()=>{const k=EVENTS.length+"|"+(EVENTS[EVENTS.length-1]||{}).id;if(k!==UP_KEY){UP_KEY=k;UP_VAL=dedupeEvents(EVENTS.filter(e=>e.utcEnd>=NOW-36e5));}return UP_VAL;};
const RANK={week:0,spotlight:1,featured:2};

const st={mode:"list",month:"",day:null,ignoreDate:false,limit:40,sig:"",allWeeks:false,view:"home",hub:"all",type:"all",topic:null,q:"",date:"any",week:null,sort:"date",evId:null,prev:"home",ysOnly:false};

function badge(p){return p==="week"?'<span class="badge b-week">Sponsor</span>':p==="spotlight"?'<span class="badge b-spot">★ Yorkseed</span>':p==="featured"?'<span class="badge b-feat">★ Featured</span>':"";}
function yourTime(e){if(e.noTime)return"";const tz=hubById(e.hub).tz;if(tzOff(e.utc,tz)===tzOff(e.utc,myTz))return"";const s=dKey(e.utc,myTz)!==dKey(e.utc,tz)?(dKey(e.utc,myTz)>dKey(e.utc,tz)?" (+1 day)":" (−1 day)"):"";return`${fE(e,myTz)} your time${s}`;}
function updSavedN(){const n=upcoming().filter(e=>saved.has(e.id)).length;document.querySelectorAll(".savedn").forEach(x=>x.textContent=n?` (${n})`:"");}
function showSaved(){const m=document.getElementById("mnav");if(m)m.hidden=true;st.savedOnly=true;st.hub="all";st.type="all";st.topic=null;st.q="";st.ysOnly=false;st.week=null;st.day=null;st.date="any";goCity(null,true);}
function heartBtn(e,cls){return`<button class="${cls}" type="button" data-save="${e.id}" aria-pressed="${saved.has(e.id)}" aria-label="Save event"><svg class="ico" style="width:17px;height:17px"><use href="#i-heart"/></svg></button>`;}

// ---------- views ----------
// ---------- shareable event links (#e/<slug>) ----------
function evSlug(e){return ((e.title||"event").toLowerCase().normalize("NFKD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"").slice(0,70)||"event")+"-"+(e.d0||e.date);}
/* Whether this event has a REAL /e/<slug>/ page already built: must match scripts/build_list_pages.py's own
   window (TODAY..TODAY+120 days, see HORIZON) exactly, or this and the static site disagree about which events
   got a static page. Used to require e.fj too (set only on Yorkseed/PULSE/live-feed events, never on the
   thousands of baked events.json entries from BAKED_EVENTS/MORE/MORE2) -- so evStatic() was false for virtually
   every ordinary event, and clicking one anywhere in the SPA (goEvent() -> evPath()) fell back to a bare
   "#e/<slug>" hash. A bare hash has no leading "/", so history.pushState/replaceState keeps whatever pathname
   the visitor was already on and just appends the hash -- which is why, e.g., clicking any non-Yorkseed event
   from a conference week's hub page left that week's URL in the address bar with the wrong event's hash stuck
   on the end, instead of navigating to that event's own page. */
function evStatic(e){if(e.mine||(e.live&&!e.fj))return false; /* just submitted or approved since the last build: no page yet */
  const n=Date.now()-5*36e5,t=new Date(n).toISOString().slice(0,10),z=new Date(n+120*864e5).toISOString().slice(0,10),a=e.d0||e.date;return !!((e.until||a)>=t&&a<=z);}
/* never a #hash link: an event with its own page gets /e/<slug>/ (real link preview), anything else ?e=<slug> */
function evPath(e){return evStatic(e)?"/e/"+evSlug(e)+"/":"?e="+evSlug(e);}
function evUrl(e){return evStatic(e)?"https://list.yorkseed.co/e/"+evSlug(e)+"/":"https://list.yorkseed.co/?e="+evSlug(e);}
