/* Open the visitor's own city on landing: the geo-city edge function sets ys_geo (lat|lon|country) from Netlify's
   location data. Only on a bare visit (no #link), only within ~500 km of a city; shared links and search engines are untouched. */
function nearHub(){try{const m=document.cookie.match(/(?:^|; )ys_geo=([^;]+)/);if(!m)return null;const [la,lo]=decodeURIComponent(m[1]).split("|").map(Number);if(!isFinite(la)||!isFinite(lo))return null;
  const R=Math.PI/180;let best=null,bd=1e9;for(const [id,[a,b]] of Object.entries(HUB_LL)){if(!hubById(id))continue;const d=6371*Math.acos(Math.min(1,Math.sin(la*R)*Math.sin(a*R)+Math.cos(la*R)*Math.cos(a*R)*Math.cos((lo-b)*R)));if(d<bd){bd=d;best=id;}}
  return bd<=500?best:null;}catch(e){return null;}}
function evBySlug(s){return EVENTS.find(x=>evSlug(x)===s);}
let PENDING_EV=null;
function openFromHash(){const m=(location.hash||"").match(/^#e\/(.+)$/);
  /* pm ("path mode") is for a fresh load/share link landing directly on an event's own /e/<slug>/ URL with no
     hash. It must NOT fire on a later hashchange while already on that page (e.g. clicking "See all events in
     Paris", href="#paris", from an open event): without the !location.hash guard, pm stayed true purely because
     the pathname was still /e/<slug>/, so this function re-resolved to the SAME event, replaceState()'d the
     #paris hash straight back off the URL, and returned true -- which made the hashchange handler's
     `if(openFromHash())return;` bail before ever calling openListFromHash("#paris"), so the click silently did
     nothing. */
  let s;const pm=/^\/e\//.test(location.pathname)&&!m&&!location.hash;const origPmPath=pm&&(location.pathname+location.search);
  if(m)s=decodeURIComponent(m[1]);else if(pm)s=decodeURIComponent(location.pathname.replace(/^\/e\/|\/$/g,""));else return false;
  let e=evBySlug(s);
  /* The event may be gone from every live source entirely -- aged out of master.json's upstream feed and never
     reached the Railway APIs (MGR_API/SUB_API), so no amount of waiting for async data will ever resolve it via
     evBySlug(). Its own static /e/<slug>/ page still carries a small window.YS_EVENT blob (baked in at build time
     from the exact data that page was generated from, see build_list_pages.py's EVENT_HTML_DATA), so synthesize a
     one-off event object from that instead of leaving PENDING_EV stuck forever and falling back to the home view. */
  if(!e&&pm&&window.YS_EVENT&&!EVENTS.some(x=>x.link&&x.link===window.YS_EVENT.link)){
    try{const synth=dbEvent("static_"+s,window.YS_EVENT);if(evSlug(synth)===s){synth.fj=1;EVENTS.push(synth);e=synth;}}catch(err){}
  }
  if(e){PENDING_EV=null;if(st.view!=="event"||st.evId!==e.id){
    const was=NAV_SILENT;NAV_SILENT=NAV_SILENT||!(history.state&&history.state.ys);try{goEvent(e.id);}finally{NAV_SILENT=was;}
    /* Landing directly on an event's own /e/<slug>/ URL (a shared link, a search hit, a fresh tab) is always a
       first navigation in this session -- st.view was still its boot default ("home") when goEvent() ran, so its
       own st.prev=st.view logic just set st.prev to "home", which would otherwise leave "BACK TO EVENTS"
       returning to the marketing home screen instead of the global events list the person actually expects
       "back" to mean here. Overwrite it after goEvent() runs, so this isn't immediately clobbered by it. */
    if(pm)st.prev="city";
    /* loaded from the event's own clean /e/<slug>/ URL: keep that exact URL (captured before goEvent/show ran -- an
       event whose date has since aged out of the static-build window makes navUrl() fall back to a #e/ hash, which
       would otherwise overwrite the real path too) rather than letting show()/navUrl() swap it for a #e/ hash. */
    if(pm){try{history.replaceState(navState(),"",origPmPath);}catch(err){}}}
    return true;}
  /* Not resolved yet (events.json still loading). If the slug's own date falls in the static-build window, a real /e/<slug>/ page already exists on disk — jump straight there instead of sitting on a #e/ URL that strips to a generic preview when shared before the JS data finishes loading.
     Skip this when we just came FROM that exact static page (its own "Add to calendar · Share" link sends people here on purpose to reach the interactive app) -- otherwise we'd bounce them straight back before the Share button ever mounts. */
  const cameFromOwnStatic=pm||(()=>{try{return document.referrer&&new URL(document.referrer).pathname===("/e/"+s+"/");}catch(err){return false;}})();
  const dm=s.match(/-(\d{4}-\d{2}-\d{2})$/);if(dm&&!cameFromOwnStatic&&!window.YS_QE){const n=Date.now()-5*36e5,t=new Date(n).toISOString().slice(0,10),z=new Date(n+120*864e5).toISOString().slice(0,10);if(dm[1]>=t&&dm[1]<=z){location.replace("https://list.yorkseed.co/e/"+s+"/");return true;}}
  PENDING_EV=s;return false;}
function setEvHash(e){try{history.replaceState(null,"",evPath(e));}catch(err){}}
function clearEvHash(){try{if(/^#e\//.test(location.hash)||/^\/e\//.test(location.pathname))history.replaceState(null,"",APP_PATH+location.search);}catch(err){}}
window.addEventListener("hashchange",()=>{if(openFromHash())return;const h=location.hash;if(h&&h!==listHash()||st.view!=="city"){const was=NAV_SILENT;NAV_SILENT=true;try{openListFromHash(h);}finally{NAV_SILENT=was;}}});
// ---------- add to calendar ----------
function calTimes(e){const pad=n=>String(n).padStart(2,"0");const z=t=>{const d=new Date(t);return d.getUTCFullYear()+pad(d.getUTCMonth()+1)+pad(d.getUTCDate())+"T"+pad(d.getUTCHours())+pad(d.getUTCMinutes())+"00Z";};
  if(e.noTime){const a=e.date.replace(/-/g,""),nd=new Date(e.date+"T12:00:00Z");nd.setUTCDate(nd.getUTCDate()+1);const b=nd.toISOString().slice(0,10).replace(/-/g,"");return{allDay:true,start:a,end:b};}
  const end=e.end?e.utcEnd:(e.utc+2*36e5);return{allDay:false,start:z(e.utc),end:z(end)};}
function calText(e){const h=hubById(e.hub);return{title:e.title,where:placeText(e,h),details:[(e.desc||"").slice(0,600),e.link?"Register: "+refLink(e.link,"calendar"):"","Found on The Yorkseed List: "+evUrl(e)].filter(Boolean).join("\n\n")};}
function gcalUrl(e){const t=calTimes(e),x=calText(e);return"https://calendar.google.com/calendar/render?action=TEMPLATE&text="+encodeURIComponent(x.title)+"&dates="+t.start+"/"+t.end+"&details="+encodeURIComponent(x.details)+"&location="+encodeURIComponent(x.where);}
function outlookUrl(e){const t=calTimes(e),x=calText(e);const iso=s=>s.length===8?s.slice(0,4)+"-"+s.slice(4,6)+"-"+s.slice(6,8):s.slice(0,4)+"-"+s.slice(4,6)+"-"+s.slice(6,8)+"T"+s.slice(9,11)+":"+s.slice(11,13)+":00Z";return"https://outlook.live.com/calendar/0/deeplink/compose?path=/calendar/action/compose&rru=addevent&subject="+encodeURIComponent(x.title)+"&startdt="+encodeURIComponent(iso(t.start))+"&enddt="+encodeURIComponent(iso(t.end))+(t.allDay?"&allday=true":"")+"&body="+encodeURIComponent(x.details)+"&location="+encodeURIComponent(x.where);}
function icsFor(e){const t=calTimes(e),x=calText(e);const q=s=>String(s).replace(/\\/g,"\\\\").replace(/;/g,"\\;").replace(/,/g,"\\,").replace(/\r?\n/g,"\\n");const now=new Date().toISOString().replace(/[-:]/g,"").replace(/\.\d+/,"");
  return["BEGIN:VCALENDAR","VERSION:2.0","PRODID:-//Yorkseed//The Yorkseed List//EN","CALSCALE:GREGORIAN","METHOD:PUBLISH","BEGIN:VEVENT","UID:"+evSlug(e)+"@list.yorkseed.co","DTSTAMP:"+now,(t.allDay?"DTSTART;VALUE=DATE:":"DTSTART:")+t.start,(t.allDay?"DTEND;VALUE=DATE:":"DTEND:")+t.end,"SUMMARY:"+q(x.title),"DESCRIPTION:"+q(x.details),"LOCATION:"+q(x.where),"URL:"+evUrl(e),"END:VEVENT","END:VCALENDAR"].join("\r\n");}
function downloadIcs(e){try{const b=new Blob([icsFor(e)],{type:"text/calendar;charset=utf-8"});const u=URL.createObjectURL(b);const a=document.createElement("a");a.href=u;a.download=evSlug(e)+".ics";document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(u);a.remove();},1500);}catch(err){toast("Couldn't create the calendar file.");}}
function calMenu(e,btn){let m=document.getElementById("calMenu");if(m){m.remove();return;}
  m=document.createElement("div");m.id="calMenu";m.className="calmenu";
  m.innerHTML=`<a href="${gcalUrl(e)}" target="_blank" rel="noopener">Google Calendar</a><button type="button" data-ics="1">Apple Calendar (.ics)</button><a href="${outlookUrl(e)}" target="_blank" rel="noopener">Outlook.com</a><button type="button" data-ics="1">Outlook desktop (.ics)</button>`;
  m.querySelectorAll("[data-ics]").forEach(b=>b.onclick=()=>{downloadIcs(e);m.remove();});
  m.querySelectorAll("a").forEach(a=>a.addEventListener("click",()=>setTimeout(()=>m.remove(),50)));
  btn.closest(".two").insertAdjacentElement("afterend",m);}
function shareMenu(btn,msg,url,title){let m=document.getElementById("shareMenu");if(m){m.remove();return;}
  const full=msg.includes(url)?msg:msg+" "+url,q=encodeURIComponent;
  m=document.createElement("div");m.id="shareMenu";m.className="calmenu";
  m.innerHTML=`<a href="https://wa.me/?text=${q(full)}" target="_blank" rel="noopener">Share on WhatsApp</a><a href="https://www.linkedin.com/sharing/share-offsite/?url=${q(url)}" target="_blank" rel="noopener">Share on LinkedIn</a><a href="https://twitter.com/intent/tweet?text=${q(msg.replace(url,"").trim())}&url=${q(url)}" target="_blank" rel="noopener">Share on X</a><button type="button" data-copy="1">Copy link</button>`+(navigator.share?`<button type="button" data-more="1">More…</button>`:"");
  m.querySelector("[data-copy]").onclick=async()=>{try{await navigator.clipboard.writeText(url);toast("Link copied. Paste it anywhere to share.");}catch(err){toast(url);}m.remove();};
  const mo=m.querySelector("[data-more]");if(mo)mo.onclick=async()=>{m.remove();try{await navigator.share({title,text:msg,url});}catch(err){}};
  m.querySelectorAll("a").forEach(a=>a.addEventListener("click",()=>setTimeout(()=>m.remove(),50)));
  (btn.closest(".two")||btn.parentElement).insertAdjacentElement("afterend",m);}
function shareEv(e,btn){const h=hubById(e.hub),d=dParts(e.date),url=evUrl(e),P=window.YS_PATHS||{},w=e.week&&weekById(e.week),wp=w&&P.w&&P.w[e.week];
  const when=`${d.long}${e.noTime?"":", "+fE(e,h.tz)}`;
  let msg=w&&wp?`Heading to ${w.name}? ${e.title} (${when}) looks worth it: ${url}\nEvery side event, sorted by role: https://list.yorkseed.co/${wp.e||wp.s}/`:`${e.title} (${when}, ${h.name}) is on The Yorkseed List: ${url}`;
  shareMenu(btn||$("#shareBtn"),msg,url,e.title);}
/* each screen is its own browser history step, so swipe-back and the Back button return to the previous screen */
let NAV_SILENT=false,NAV_DEPTH=0;
function navKey(){return st.view+"|"+(st.view==="city"?st.hub+"|"+(st.week||"")+"|"+(st.day||""):"")+"|"+(st.view==="event"?st.evId:"");}
function navState(){return{ys:1,view:st.view,hub:st.hub,evId:st.evId,week:st.week||null,day:st.day||null};}
function navUrl(){const e=st.view==="event"&&EVENTS.find(x=>x.id===st.evId);if(e)return evPath(e);if(st.view==="city"&&!st.savedOnly)return listUrl();return APP_PATH+location.search;}
/* shareable list links: #<city>, #events, #w/<week>, #w/<week>/<YYYY-MM-DD> */
/* readable list links: #web-summit-lisbon, #web-summit-lisbon/2026-11-09, #lisbon, #events (old #w/<id> and #<hub id> still open) */
function nslug(t){return String(t||"").toLowerCase().normalize("NFKD").replace(/[\u0300-\u036f]/g,"").replace(/&/g," and ").replace(/\b(19|20)\d\d\b/g,"").replace(/[^a-z0-9]+/g,"-").replace(/^-+|-+$/g,"");}
function hubSlug(h){const P=window.YS_PATHS;return (P&&P.h&&P.h[h.id])||nslug(h.name);}
function weekSlug(w){return nslug(w.name);}
const LIST_BASE=/^list\./.test(location.hostname)?"/":"/list/";
function listPathFor(w,day,hubId){const P=window.YS_PATHS;if(!P)return"";if(w){const wp=P.w&&P.w[w.id];if(!wp)return"";if(day&&(wp.d||[]).includes(day))return LIST_BASE+wp.s+"/"+day+"/";return LIST_BASE+wp.s+"/";}const hs=hubId&&P.h&&P.h[hubId];return hs?LIST_BASE+hs+"/":"";}
function listUrl(){const w=st.week&&weekById(st.week);if(w)return listPathFor(w,st.day)||listHash();if(st.hub&&st.hub!=="all")return listPathFor(null,null,st.hub)||listHash();return listHash();}
function listHash(){const w=st.week&&weekById(st.week);if(w)return "#"+weekSlug(w)+(st.day?"/"+st.day:"");const h=st.hub&&st.hub!=="all"&&hubById(st.hub);return h?"#"+hubSlug(h):"#events";}
let NAV_SHOWING=false;
/* Never true on the home page's own "/" (hash-routed) city switches, only on a dedicated clean static path
   (/paris/, /web-summit-lisbon/2026-11-09/, …) that was already correct when the page loaded: leave it alone
   instead of rewriting it into a #hash form. */
function syncListUrl(){if(NAV_SHOWING||st.view!=="city"||st.savedOnly)return;const u=listUrl();const same=u.charAt(0)==="#"?location.hash===u:(location.pathname===u&&!location.hash);if(!same){try{history.replaceState(navState(),"",u);}catch(err){}}}
function openListFromHash(h){h=decodeURIComponent((h||"").replace(/^#/,"")).toLowerCase();
  const goWeek=(w,day)=>{st.week=w.id;st.topic=null;st.q="";st.ysOnly=false;st.date="any";st.type="all";goCity(w.hub);day=day||firstCoreDay(w);if(day){st.day=day;st.mode="list";renderCity();}return true;};
  let m=h.match(/^w\/([a-z0-9]+)(?:\/(\d{4}-\d{2}-\d{2}))?$/);if(m&&weekById(m[1]))return goWeek(weekById(m[1]),m[2]);
  if(h==="events"){st.week=null;goCity("all");return true;}
  m=h.match(/^([a-z0-9-]+)(?:\/(\d{4}-\d{2}-\d{2}))?$/);if(!m)return false;
  const w=WEEKS.find(x=>weekSlug(x)===m[1]);if(w)return goWeek(w,m[2]);
  const hb=HUBS.find(x=>x.id===m[1]||hubSlug(x)===m[1]);if(hb&&!m[2]){st.week=null;goCity(hb.id);return true;}return false;}
/* Hydrating a static page from its own clean URL (/paris/, /web-summit-lisbon-2026-side-events/, …) uses the
   REAL file-path slugs the Python build gave those pages (window.YS_PATHS), which carry a year/suffix the
   #hash form above never did (weekSlug()/openListFromHash() match the short #hash form, a different scheme) --
   so this matches against YS_PATHS.w[id].s/.e directly instead of recomputing a slug client-side. */
function openFromPath(path){
  const P=window.YS_PATHS||{h:{},w:{}};
  const m=path.match(/^([a-z0-9-]+)(?:\/(\d{4}-\d{2}-\d{2}))?$/);if(!m)return false;
  const seg=m[1],day=m[2];
  const goWeek=(w,d)=>{st.week=w.id;st.topic=null;st.q="";st.ysOnly=false;st.date="any";st.type="all";goCity(w.hub);d=d||firstCoreDay(w);if(d){st.day=d;st.mode="list";renderCity();}return true;};
  for(const w of WEEKS){const wp=P.w&&P.w[w.id];if(wp&&(wp.s===seg||wp.e===seg))return goWeek(w,day);}
  const hb=HUBS.find(x=>hubSlug(x)===seg);if(hb&&!day){st.week=null;goCity(hb.id);return true;}
  return false;}
function listShareUrl(){const P=window.YS_PATHS||{h:{},w:{}},L="https://list.yorkseed.co/";const w=st.week&&weekById(st.week);
  if(w){const wp=P.w&&P.w[w.id];if(wp){if(st.day&&(wp.d||[]).includes(st.day))return L+wp.s+"/"+st.day+"/";return L+(wp.e||wp.s)+"/";}return L+listHash();}
  if(st.hub&&st.hub!=="all"){const hs=P.h&&P.h[st.hub];return hs?L+hs+"/":L+"#"+st.hub;}
  return L+"#events";}
function shareList(ev){const url=listShareUrl(),w=st.week&&weekById(st.week),h=st.hub&&st.hub!=="all"?hubById(st.hub):null;
  const title=w?`${w.name} side events${st.day?" · "+dParts(st.day).long:""} · The Yorkseed List`:h?`Tech, startup & venture events in ${h.name} · The Yorkseed List`:"The Yorkseed List: tech, startup & venture events worldwide";
  const msg=w?`Every ${w.name} side event, sorted by role: ${url}`:h?`Tech, startup & venture events in ${h.name}: ${url}`:`The Yorkseed List, tech, startup & venture events worldwide: ${url}`;
  shareMenu((ev&&ev.currentTarget)||$("#cityShare"),msg,url,title);}
function show(view,prevKey){
  if(prevKey===undefined)prevKey=navKey();
  if(!NAV_SILENT){try{history.replaceState({...(history.state&&history.state.ys?history.state:navState()),y:scrollY},"");}catch(err){}}
  st.view=view;
  $("#vHome").hidden=view!=="home";$("#vCity").hidden=view!=="city";$("#vEvent").hidden=view!=="event";
  NAV_SHOWING=true;try{if(view==="city")renderCity();if(view==="event")renderEvent();}finally{NAV_SHOWING=false;}
  scrollTo({top:0,behavior:"instant"});
  if(navKey()!==prevKey){try{if(NAV_SILENT)history.replaceState(navState(),"",navUrl());else{history.pushState(navState(),"",navUrl());NAV_DEPTH++;}}catch(err){}}
}
function goCity(hub,keepSaved){const k=navKey();if(!keepSaved)st.savedOnly=false;if(hub)st.hub=hub;st.day=null;st.month="";st.prev="city";show("city",k);}
function goEvent(id){const k=navKey();st.prev=st.view==="event"?st.prev:st.view;st.evId=id;show("event",k);}
window.addEventListener("popstate",ev=>{const s=ev.state;NAV_SILENT=true;
  try{if(s&&s.ys){NAV_DEPTH=Math.max(0,NAV_DEPTH-1);if(s.hub)st.hub=s.hub;if((s.view||"home")==="city"){st.week=s.week||null;st.day=s.day||null;}if(s.evId)st.evId=s.evId;show(s.view||"home");const y=s.y||0;requestAnimationFrame(()=>requestAnimationFrame(()=>scrollTo({top:y,behavior:"instant"})));}
      else if(!openFromHash()&&!openListFromHash(location.hash))show("home");}finally{NAV_SILENT=false;}});

// home
function renderHome(){
  $("#heroImg").src=IMG.hero;$("#partnerImg").src=IMG.partner;
  $("#hHub").innerHTML='<option value="all">All Cities</option>'+HUBS.map(h=>`<option value="${h.id}">${h.name}</option>`).join("");
  $("#pills").innerHTML=TOPICS.map(t=>`<button class="pill" type="button" data-topic="${t}">${t}</button>`).join("");
  renderCityRow();
  const FR={spotlight:0,featured:1,week:2};const feat=upcoming().filter(e=>e.place).sort((a,b)=>(FR[a.place]-FR[b.place])||a.utc-b.utc);
  const pick=[];const seen=new Set();for(const e of feat){if(!seen.has(e.hub)||pick.length>=4-0){if(pick.length<4&&!seen.has(e.hub)){pick.push(e);seen.add(e.hub);}}}
  for(const e of feat){if(pick.length>=4)break;if(!pick.includes(e))pick.push(e);}
  pick.sort((a,b)=>a.utc-b.utc);
  $("#featCards").innerHTML=pick.map(e=>{const h=hubById(e.hub),d=dParts(e.date);return`<article class="card" data-ev="${e.id}" tabindex="0">
    <div class="ph">${evImgTag(e,IMG[e.img])}${badge(e.place)}${heartBtn(e,"heart")}</div>
    <div class="body"><h3>${esc(e.title)}</h3>
      <div class="meta">${ico("cal")}${d.long}${e.noTime?"":" · "+fE(e,h.tz)}</div>
      <div class="meta">${ico("pin")}${h.name}</div>
      <div class="tags">${e.tags.slice(0,3).map(t=>`<span class="tag">${esc(t)}</span>`).join("")}</div></div></article>`}).join("");
  renderWeeks();renderUpcoming();renderBanners();
  {const tot=upcoming().length,c=new Set(upcoming().filter(e=>e.hub!=="virtual").map(e=>e.hub)).size;$("#cityN").textContent=c;const _x=0,wk=upcoming().filter(e=>e.date<=addDays(6)).length;$("#heroStat").innerHTML=`<b>${tot}</b> events · <b>${c}</b> cities · <b>${wk}</b> this week`;}
}
function hubCount(id){return upcoming().filter(e=>e.hub===id).length;}
const YS_HOSTS=["Yorkseed","Valois","Yorkseed Expert Series"];
function ysHubCount(id){return upcoming().filter(e=>e.hub===id&&YS_HOSTS.includes(e.host)).length;}
function renderCityRow(){
  const t=Date.now();
  $("#cityRow").innerHTML=[...HUBS].filter(h=>h.id!=="virtual").sort((a,b)=>hubCount(b.id)-hubCount(a.id)).slice(0,8).map(h=>{const n=hubCount(h.id);return h.img?`<a class="city" href="${listPathFor(null,null,h.id)||"#"+hubSlug(h)}" data-city="${h.id}"><img src="${IMG[h.img]}" alt="" style="object-position:${IMGPOS[h.img]||"50% 50%"}"><span class="clk">${fT(t,h.tz)}</span><span><b>${h.name}</b>${n} event${n===1?"":"s"}</span></a>`:`<a class="city noimg" href="${listPathFor(null,null,h.id)||"#"+hubSlug(h)}" data-city="${h.id}"><span class="clk">${h.id==="virtual"?"Online":fT(t,h.tz)}</span><i>${h.code}</i><span><b>${h.name}</b>${n} event${n===1?"":"s"}</span></a>`}).join("");
  renderMap();
}
const REGIONS=[["world","World"],["na","North America"],["eu","Europe"],["mea","Middle East & Asia"],["latam","Latin America"],["oc","Australia"]];
const REG_OF={nyc:"na",sf:"na",atx:"na",bos:"na",chi:"na",la:"na",mia:"na",dc:"na",mtl:"na",tor:"na",ams:"eu",bcn:"eu",ber:"eu",can:"eu",cph:"eu",dub:"eu",hel:"eu",lis:"eu",ldn:"eu",mil:"eu",muc:"eu",par:"eu",sto:"eu",zrh:"eu",bue:"latam",mex:"latam",sao:"latam",tlv:"mea",dxb:"mea",hkg:"mea",kul:"mea",sgp:"mea",syd:"oc",sea:"na",tyo:"mea",blr:"mea",mad:"eu",yvr:"na",den:"na",sel:"mea",tpe:"mea",bkk:"mea",jkt:"mea",nbo:"mea",los:"mea",mel:"oc",phl:"na",waw:"eu"};
const MZ={k:1,x:0,y:0,region:"world",built:false};
function mapSvgPt(svg,cx,cy){const p=svg.createSVGPoint();p.x=cx;p.y=cy;return p.matrixTransform(svg.getScreenCTM().inverse());}
function clampMZ(){const W=MAP.W,H=MAP.H;MZ.k=Math.max(1,Math.min(150,MZ.k));MZ.x=Math.min(0,Math.max(W-W*MZ.k,MZ.x));MZ.y=Math.min(0,Math.max(H-H*MZ.k,MZ.y));}
function zoomAt(f,px,py){const k2=Math.max(1,Math.min(150,MZ.k*f));const r=k2/MZ.k;MZ.x=px-(px-MZ.x)*r;MZ.y=py-(py-MZ.y)*r;MZ.k=k2;clampMZ();drawMZ();}
function fitRegion(id){MZ.region=id;if(id==="world"){MZ.k=1;MZ.x=0;MZ.y=0;}else{const ps=HUBS.filter(h=>REG_OF[h.id]===id&&MAP.pts[h.id]).map(h=>MAP.pts[h.id]);const xs=ps.map(p=>p[0]),ys=ps.map(p=>p[1]);const x0=Math.min(...xs),x1=Math.max(...xs),y0=Math.min(...ys),y1=Math.max(...ys);const pad=id==="oc"?260:110;const k=Math.min(MAP.W/(x1-x0+pad*2),MAP.H/(y1-y0+pad*2),9);MZ.k=k;MZ.x=MAP.W/2-(x0+x1)/2*k;MZ.y=MAP.H/2-(y0+y1)/2*k;clampMZ();}
  document.querySelectorAll("#regions button").forEach(b=>b.setAttribute("aria-pressed",String(b.dataset.reg===id)));drawMZ();}
function starPath(R){const r=R*.45;let d="";for(let i=0;i<10;i++){const a=-Math.PI/2+i*Math.PI/5,rr=i%2?r:R;d+=(i?"L":"M")+(Math.cos(a)*rr).toFixed(1)+" "+(Math.sin(a)*rr).toFixed(1);}return d+"Z";}
function featCount(id){return upcoming().filter(e=>e.hub===id&&(e.place==="featured"||e.place==="week")).length;}
function isHouse(e){return/yorkseed\s+house/i.test((e&&e.title)||"")||!!(e&&e.house);}
function hsCount(id){return upcoming().filter(e=>e.hub===id&&isHouse(e)).length;}
function hsBadge(e){return isHouse(e)?'<span class="badge b-hs">■ Yorkseed House</span>':"";}
function cpCount(id){return upcoming().filter(e=>e.hub===id&&e.partner).length;}
function ysCount(id){return upcoming().filter(e=>e.hub===id&&e.place==="spotlight").length;}
function drawMZ(){
  const g=$("#mzLand");if(!g)return;g.setAttribute("transform",`translate(${MZ.x} ${MZ.y}) scale(${MZ.k})`);
  const counts=HUBS.filter(h=>MAP.pts[h.id]).map(h=>({h,n:hubCount(h.id)})).sort((a,b)=>a.n-b.n);
  const showAll=MZ.k>=2.2,top=new Set([...counts].sort((a,b)=>b.n-a.n).slice(0,6).map(c=>c.h.id));
  const inView=[],LAB=new Map(),boxes=[];
  const ctrs=counts.map(({h,n})=>{const [px,py]=MAP.pts[h.id];return [h.id,px*MZ.k+MZ.x,py*MZ.k+MZ.y];});
  counts.forEach(({h,n})=>{if(!(showAll||top.has(h.id)))return;const [px,py]=MAP.pts[h.id];const x=px*MZ.k+MZ.x,y=py*MZ.k+MZ.y;const r=(n?15+Math.min(Math.sqrt(n),6.5)*5:9)+4;boxes.push([x-r,y-r,x+r,y+r]);});
  const top3=new Set([...counts].sort((a,b)=>b.n-a.n).slice(0,3).map(c=>c.h.id));
  [...counts].sort((a,b)=>b.n-a.n).forEach(({h,n})=>{if(!(showAll||top.has(h.id)))return;const [px,py]=MAP.pts[h.id];const x=px*MZ.k+MZ.x,y=py*MZ.k+MZ.y;const r=n?15+Math.min(Math.sqrt(n),6.5)*5:9;const w=h.name.length*19+8;
    const opts=[["r",x+r+9,y-16],["l",x-r-9-w,y-16],["t",x-w/2,y-r-40],["b",x-w/2,y+r+6]];let pick=null;
    for(const [sd,x0,y0] of opts){const bx=[x0,y0,x0+w,y0+32];if(!boxes.some(c=>bx[0]<c[2]&&bx[2]>c[0]&&bx[1]<c[3]&&bx[3]>c[1])&&!ctrs.some(([id,cx,cy])=>id!==h.id&&cx>bx[0]-6&&cx<bx[2]+6&&cy>bx[1]-4&&cy<bx[3]+4)){pick=[sd,bx];break;}}
    if(!pick&&top3.has(h.id))pick=["r",[x+r+9,y-16,x+r+9+w,y+16]];
    if(pick){boxes.push(pick[1]);LAB.set(h.id,pick[0]);}});
  $("#mzDots").innerHTML=counts.map(({h,n})=>{const [px,py]=MAP.pts[h.id];const x=px*MZ.k+MZ.x,y=py*MZ.k+MZ.y;if(x<-40||y<-40||x>MAP.W+40||y>MAP.H+40)return"";if(x>=0&&y>=0&&x<=MAP.W&&y<=MAP.H)inView.push({h,n});const r=n?15+Math.min(Math.sqrt(n),6.5)*5:9;
    return`<g class="hubdot${n?"":" zero"}" data-city="${h.id}" tabindex="0" role="button" aria-label="${h.name}: ${n} event${n===1?"":"s"}" transform="translate(${x.toFixed(1)} ${y.toFixed(1)})"><circle r="${r+9}" class="halo"/><circle r="${r}"/>${n?`<text class="cnt" dy="8" text-anchor="middle">${n}</text>`:""}${featCount(h.id)?`<path class="fstar" transform="translate(${(-r*.85).toFixed(1)} ${(-r*.85).toFixed(1)})" d="${starPath(27)}"/>`:""}${hsCount(h.id)?`<rect class="hsq" x="${(-r*.85-14).toFixed(1)}" y="${(r*.8-14).toFixed(1)}" width="28" height="28" rx="2"/>`:""}${cpCount(h.id)?`<path class="cptri" transform="translate(${(r*.85).toFixed(1)} ${(r*.8).toFixed(1)})" d="M0 -20 L18 12 L-18 12 Z"/>`:""}${ysCount(h.id)?`<path class="ystar" transform="translate(${(r*.85).toFixed(1)} ${(-r*.85).toFixed(1)})" d="${starPath(27)}"/>`:""}${LAB.has(h.id)?(()=>{const sd=LAB.get(h.id);return`<text class="lbl" x="${sd==="r"?r+9:sd==="l"?-(r+9):0}" y="${sd==="t"?-(r+14):sd==="b"?r+28:0}" text-anchor="${sd==="r"?"start":sd==="l"?"end":"middle"}" dy="${sd==="t"||sd==="b"?0:10}">${h.name}</text>`;})():""}</g>`}).join("");
  const sp=allBookings().filter(b=>b.kind==="map"&&b.hub&&MAP.pts[b.hub]);
  $("#mzDots").insertAdjacentHTML("beforeend",sp.map(b=>{const [px,py]=MAP.pts[b.hub];const x=px*MZ.k+MZ.x,y=py*MZ.k+MZ.y;if(x<-200||y<-80||x>MAP.W+200||y>MAP.H+80)return"";const w=Math.max(230,(b.headline||b.brand).length*15+90);
    return`<a class="spin-pin" href="${esc(b.url||"#")}" target="_blank" rel="noopener" transform="translate(${x.toFixed(1)} ${y.toFixed(1)})"><path class="sp-tail" d="M-12 -44 L0 -20 L12 -44 Z"/><rect class="sp-box" x="${-w/2}" y="-112" width="${w}" height="68"/><path class="fstar" transform="translate(${-w/2+34} -78)" d="${starPath(18)}"/><text class="sp-lab" x="${-w/2+62}" y="-86">FEATURED EVENT</text><text class="sp-name" x="${-w/2+62}" y="-58">${esc(b.headline||b.brand)}</text></a>`}).join(""));
  $("#mzLegendSp").hidden=!sp.length&&!HUBS.some(h=>featCount(h.id));
  inView.sort((a,b)=>b.n-a.n);const tot=inView.reduce((t,c)=>t+c.n,0);
  $("#inviewHead").innerHTML=`<b>${tot}</b> events in view`;$("#mzPill").innerHTML=`<b>${tot}</b> events in view · ${inView.filter(c=>c.n).length} cities`;
  $("#inviewList").innerHTML=inView.filter(c=>c.n).map(({h,n})=>`<li><button type="button" data-city="${h.id}">${h.name}<span>${n}</span></button></li>`).join("")||`<li class="note">No events in this area yet.</li>`;
  const v=hubCount("virtual");$("#mapStats").innerHTML=v?`<button class="link" type="button" data-city="virtual">${v} online events →</button>`:"";
}
function loadMapPaths(){if(MAP.land||loadMapPaths.busy)return;const run=()=>{if(loadMapPaths.busy)return;loadMapPaths.busy=1;
  fetch("/list/assets/map-paths.json").then(r=>r.ok?r.json():null).then(p=>{if(!p)return;MAP.land=p.land;MAP.borders=p.borders;
    const g=document.querySelectorAll("#mzLand path");if(g[0])g[0].setAttribute("d",p.land);if(g[1])g[1].setAttribute("d",p.borders);}).catch(()=>{loadMapPaths.busy=0;});};
  const sec=document.getElementById("mapsec");
  if(sec&&"IntersectionObserver" in window){const io=new IntersectionObserver(es=>{if(es.some(e=>e.isIntersecting)){io.disconnect();run();}},{rootMargin:"600px"});io.observe(sec);}else run();}
function renderMap(){
  const box=$("#worldMap");if(!box)return;
  if(!MZ.built){MZ.built=true;
    $("#regions").innerHTML=REGIONS.map(([id,l])=>`<button type="button" class="dchip" data-reg="${id}" aria-pressed="${id==="world"}">${l}</button>`).join("");
    // The land/border path data (now lazy-loaded from map-paths.json) has always spanned roughly
    // x:[-55,1944] y:[-160,1757] -- the viewBox below used to be a hardcoded "0 0 2000 1150", built from
    // MAP.W/MAP.H, which only covers x:[0,2000] y:[0,1150]. Since <svg> clips to its viewBox by default, well
    // over a third of the map's vertical extent (everything south of ~y=1150: most of South America, southern
    // Africa, Australia, Antarctica) was being silently clipped to nothing, which is why the map renders as a
    // handful of disconnected fragments instead of a recognizable world. All 49 baked-in hub dots (MAP.pts) sit
    // within y:[338,985], well inside both the old and new bounds, so they're unaffected either way -- only the
    // SVG's own viewBox/background rect needed to grow to the data's real extent; MAP.W/MAP.H (used for the
    // zoom/pan and dot-culling math elsewhere, which already tolerates some negative slack) are untouched.
    const MVB="-80 -180 2080 1960";
    box.insertAdjacentHTML("afterbegin",`<svg viewBox="${MVB}" id="mzSvg" role="img" aria-label="Interactive map of Yorkseed cities"><rect x="-80" y="-180" width="2080" height="1960" class="sea"/><g id="mzLand"><path d="${MAP.land}" class="land"/><path d="${MAP.borders}" class="border"/></g><g id="mzDots"></g></svg>`);
    loadMapPaths();
    const svg=$("#mzSvg"),tip=$("#mapTip"),ptrs=new Map();let start=null,moved=0,pinch=null;
    svg.addEventListener("wheel",e=>{e.preventDefault();const p=mapSvgPt(svg,e.clientX,e.clientY);zoomAt(Math.exp(-e.deltaY*0.0018),p.x,p.y);},{passive:false});
    svg.addEventListener("pointerdown",e=>{ptrs.set(e.pointerId,{x:e.clientX,y:e.clientY});if(ptrs.size===1){start={x:e.clientX,y:e.clientY,mx:MZ.x,my:MZ.y};moved=0;}else if(ptrs.size===2){const [a,b]=[...ptrs.values()];pinch={d:Math.hypot(a.x-b.x,a.y-b.y),k:MZ.k};}});
    svg.addEventListener("pointermove",e=>{if(!ptrs.has(e.pointerId))return;ptrs.set(e.pointerId,{x:e.clientX,y:e.clientY});
      if(ptrs.size===2&&pinch){const [a,b]=[...ptrs.values()];const d=Math.hypot(a.x-b.x,a.y-b.y);const c=mapSvgPt(svg,(a.x+b.x)/2,(a.y+b.y)/2);zoomAt((pinch.k*d/pinch.d)/MZ.k,c.x,c.y);moved=99;return;}
      if(start){const dx=e.clientX-start.x,dy=e.clientY-start.y;moved=Math.max(moved,Math.hypot(dx,dy));if(moved>4){if(!svg.hasPointerCapture(e.pointerId))svg.setPointerCapture(e.pointerId);const sc=MAP.W/svg.getBoundingClientRect().width;MZ.x=start.mx+dx*sc;MZ.y=start.my+dy*sc;clampMZ();drawMZ();tip.hidden=true;box.classList.add("dragging");}}});
    const up=e=>{ptrs.delete(e.pointerId);if(ptrs.size<2)pinch=null;if(!ptrs.size){box.classList.remove("dragging");const g=e.target.closest&&e.target.closest(".hubdot");if(g&&moved<=4)goCity(g.dataset.city);start=null;}};
    svg.addEventListener("pointerup",up);svg.addEventListener("pointercancel",up);
    svg.addEventListener("dblclick",e=>{const p=mapSvgPt(svg,e.clientX,e.clientY);zoomAt(2,p.x,p.y);});
    svg.addEventListener("mouseover",e=>{const g=e.target.closest(".hubdot");if(!g||start&&moved>4)return;const h=hubById(g.dataset.city),n=hubCount(h.id);const cp=cpCount(h.id),ys=ysCount(h.id),fe=featCount(h.id);tip.innerHTML=`<b>${h.name}</b><span>${n} event${n===1?"":"s"} · ${fT(Date.now(),h.tz)} local</span>${fe?`<span class="tipfe">★ ${fe} featured event${fe===1?"":"s"}</span>`:""}${ys?`<span class="tipys">★ ${ys} Yorkseed event${ys===1?"":"s"}</span>`:""}${hsCount(h.id)?`<span class="tiphs">■ ${hsCount(h.id)} Yorkseed House event${hsCount(h.id)===1?"":"s"}</span>`:""}${cp?`<span class="tipcp">▲ ${cp} Yorkseed community partner event${cp===1?"":"s"}</span>`:""}`;tip.hidden=false;const b=g.querySelector("circle:last-of-type").getBoundingClientRect(),c=box.getBoundingClientRect();tip.style.left=(b.left-c.left+b.width/2)+"px";tip.style.top=(b.top-c.top)+"px";});
    svg.addEventListener("mouseout",e=>{if(e.target.closest(".hubdot"))tip.hidden=true;});
    svg.addEventListener("keydown",e=>{const g=e.target.closest(".hubdot");if(g&&e.key==="Enter")goCity(g.dataset.city);});
    $("#zIn").onclick=()=>zoomAt(1.6,MAP.W/2,MAP.H/2);$("#zOut").onclick=()=>zoomAt(1/1.6,MAP.W/2,MAP.H/2);$("#zReset").onclick=()=>fitRegion("world");
  }
  drawMZ();
}
// Yorkseed programs (delegation, Yorkseed House) for a week. Add a "House" entry with its own url to show it.
function ysProgramsHtml(w,compact){
  if(!w||!w.ys||!w.ys.length)return"";
  const ev=upcoming().filter(e=>e.week===w.id&&e.place==="spotlight").sort((a,b)=>a.date.localeCompare(b.date)||a.utc-b.utc);
  if(compact)return`<span class="ystags">${w.ys.map(p=>`<span class="ystag">★ ${compact===2?"":"Yorkseed "}${esc(p.kind)}</span>`).join("")}</span>`;
  return`<div class="ysprog"><div class="yshead"><span class="eyebrow">★ Yorkseed at ${esc(w.name)}</span></div><div class="yscards">${w.ys.map(p=>`<div class="yscard"><span class="kind">${esc(p.kind==="House"?"Yorkseed House":"Yorkseed "+p.kind)}</span><h3>${esc(p.title)}</h3><p>${esc(p.blurb)}</p><div class="acts"><a class="btn btn-gold btn-sm" href="${esc(p.url)}" target="_blank" rel="noopener">${esc(p.cta)} →</a>${(p.more||[]).map(([l,u])=>`<a class="link" href="${esc(u)}" target="_blank" rel="noopener">${esc(l)} →</a>`).join("")}</div></div>`).join("")}${ev.length?`<div class="yscard evs"><span class="kind">Yorkseed events · ${range(w.start,w.end)}</span>${ev.map((e,i)=>{const d=dParts(e.date);return`<button class="ritem${i>=4?" more":""}" type="button" data-ev="${e.id}"><span class="rd">${d.mon} <b>${d.day}</b></span><span class="rt">${esc(e.title)}</span></button>`}).join("")}${ev.length>4?`<button class="link ysall" type="button" onclick="this.parentElement.classList.add('open');this.remove()">All ${ev.length} Yorkseed events ↓</button>`:""}</div>`:""}</div></div>`;
}
const weekOk=w=>!!w.ys||Math.max(upcoming().filter(e=>e.week===w.id).length,((((window.YS_PATHS||{}).w||{})[w.id])||{}).n||0)>=5;
function renderWeeks(){
  const today=dKey(Date.now(),myTz);
  const cnt={};upcoming().forEach(e=>{if(e.week)cnt[e.week]=(cnt[e.week]||0)+1;});
  /* the page first loads ~45 days of events and the rest when idle: use the build-time count so later weeks show right away */
  {const PW=(window.YS_PATHS||{}).w||{};Object.keys(PW).forEach(id=>{if((PW[id].n||0)>(cnt[id]||0))cnt[id]=PW[id].n;});}
  // weeks on now or starting within 10 days come first, biggest first; then the rest by date
  const soonCut=addDays(10),soon=w=>w.start<=soonCut;
  const ws=[...WEEKS].filter(w=>w.end>=today&&weekOk(w)&&(cnt[w.id]||0)>0).sort((a,b)=>(soon(b)-soon(a))||(soon(a)?(cnt[b.id]||0)-(cnt[a.id]||0):a.start.localeCompare(b.start)));
  const show=st.allWeeks?ws:[...ws.slice(0,6),...ws.slice(6).filter(w=>w.ys)];
  $("#weekGrid").innerHTML=show.map(w=>{const n=cnt[w.id]||0;const live=today>=w.start&&today<=w.end;
    const wh=hubById(w.hub),wi=WIMG[w.id]||(wh&&wh.img&&IMG[wh.img]);return`<a class="wrow" href="${listPathFor(w)||"#"+weekSlug(w)}" data-weekgo="${w.id}"><span class="wt">${wi?`<img src="${wi}" alt="" loading="lazy" decoding="async" style="object-position:${WIMG[w.id]?"50% 50%":IMGPOS[wh.img]||"50% 50%"}">`:""}</span><span class="wd">${range(w.start,w.end)}${live?'<span class="badge b-now live">This week</span>':""}</span><span class="wn">${esc(w.name)}<small>${hubById(w.hub).name} · Yorkseed Master Side Event List${w.ys?" "+ysProgramsHtml(w,true):""}</small></span><span class="wc">${n} event${n===1?"":"s"}</span><span class="ar">→</span></a>`}).join("");
  const mb=$("#moreWeeks");mb.parentElement.hidden=ws.length<=6;mb.textContent=st.allWeeks?"Show fewer":`All ${ws.length} conference weeks`;
}

// list rendering, built to stay calm at hundreds of events
const PAGE=80;
function rowHtml(e,withDate){const h=hubById(e.hub),y=yourTime(e),wk=e.week&&!st.week?weekById(e.week):null,d=dParts(e.date);
  const host=e.host===e.title?"":esc(e.host);const at=e.venue?`<span class="at">${/after (rsvp|registration|approval)/i.test(e.venue)?"· "+esc(e.venue):"at "+esc(e.venue)}</span>`:"";
  return`<div class="crow${e.noTime?" nt":""}${e.place==="featured"?" feat":""}${e.place==="spotlight"?" ys":""}"><div class="t">${withDate?`${d.wd} ${d.day} ${d.mon}<small>${fE(e,h.tz)} ${abE(e,h.tz)}</small>`:e.noTime?`<small style="padding-top:5px;color:var(--ink)">${st.hub==="all"||st.view==="home"?esc(h.code):esc(e.type)}</small>`:`${fE(e,h.tz)}<small>${abE(e,h.tz)}</small>`}</div>
  <button class="main" type="button" data-ev="${e.id}"><span class="ttl">${esc(e.title)} ${spanOf(e)?`<span class="badge b-span">${spanOf(e)}</span>`:""}${badge(e.place)}${e.mine?'<span class="badge b-you">Yours</span>':""}${hsBadge(e)}${e.partner?'<span class="badge b-cp">▲ Yorkseed partner</span>':""}</span>
  <span class="sub">${[st.hub==="all"||st.view==="home"?h.name:"",e.noTime&&!(st.hub==="all"||st.view==="home")?"":esc(e.type),host,wk?esc(wk.name):""].filter(Boolean).join(" · ")} ${at}</span>
  <span class="meta2">${e.price?`<span class="price">${esc(e.price)}</span>`:""}${(e.aud||[]).map(a=>`<span class="aud">${esc(a)}</span>`).join("")}${e.series?`<span class="ser">${esc(e.series)}</span>`:""}${y?`<span class="yours">${y}</span>`:""}</span></button>
  ${heartBtn(e,"iconbtn")}</div>`;}
let DAYN={};
function groupedHtml(list){
  const today=dKey(NOW,myTz),tmr=dKey(NOW+864e5,myTz),cut=(st.week&&st.view==="city")||st.day?"9999":dKey(NOW+14*864e5,myTz);
  const g=[];list.forEach(e=>{const key=e.date<cut?e.date:"M"+e.date.slice(0,7);const last=g[g.length-1];if(last&&last.key===key)last.items.push(e);else g.push({key,date:e.date,items:[e]});});
  return g.map(x=>{if(x.key[0]==="M"){const d=new Date(x.key.slice(1)+"-15T12:00:00Z");const mn=new Intl.DateTimeFormat("en-US",{month:"long",timeZone:"UTC"}).format(d);const sameMonth=x.key.slice(1)===today.slice(0,7)||x.key.slice(1)===cut.slice(0,7);const yr=x.key.slice(1,5)!==today.slice(0,4)?" "+x.key.slice(1,5):"";
      return`<div class="dayhead"><h3>${sameMonth?"Later in ":""}<em>${mn}${yr}</em></h3><span>${x.items.length} event${x.items.length===1?"":"s"}</span></div>${x.items.map(e=>rowHtml(e,true)).join("")}`;}
    const d=new Date(x.date+"T12:00:00Z");const lbl=x.date===today?"Today":x.date===tmr?"Tomorrow":new Intl.DateTimeFormat("en-US",{weekday:"long",timeZone:"UTC"}).format(d);const cw=coreWeek(x.date);
    return`<div class="dayhead" data-day="${x.date}"><h3>${lbl}, <em>${new Intl.DateTimeFormat("en-US",{month:"long",day:"numeric",timeZone:"UTC"}).format(d)}</em>${cw?`<span class="coretag">${esc(cw.coreName||cw.name)} day</span>`:""}</h3><span>${DAYN[x.date]||x.items.length} event${(DAYN[x.date]||x.items.length)===1?"":"s"}</span></div>${x.items.map(e=>rowHtml(e)).join("")}`}).join("");
}
function addDays(n){return dKey(NOW+n*864e5,myTz);}
function filtered(skipType,skipTopic){
  const q=st.q.trim().toLowerCase(),today=addDays(0);
  const inDate=e=>{switch(st.date){case"today":return e.date===today;case"week":return e.date<=addDays(6);case"weekend":{const wd=new Date(e.date+"T12:00:00Z").getUTCDay();return e.date<=addDays(7)&&(wd===0||wd===6);}case"30":return e.date<=addDays(29);case"weeks":return!!e.week;default:return true;}};
  return upcoming().filter(e=>(!st.savedOnly||saved.has(e.id))&&(!st.ysOnly||["Yorkseed","Valois","Yorkseed Expert Series"].includes(e.host))&&(st.hub==="all"||e.hub===st.hub)&&(skipType||st.type==="all"||e.type===st.type||(e.cats||[]).includes(st.type))&&(skipTopic||!st.topic||e.tags.includes(st.topic)||(e.sectors||[]).includes(st.topic))&&(!st.week||e.week===st.week)&&(st.ignoreDate||((!st.day||q||e.date===st.day)&&inDate(e)))&&(!q||[e.title,e.host,e.type,hubById(e.hub).name,...e.tags].join(" ").toLowerCase().includes(q)))
    .sort((a,b)=>a.date.localeCompare(b.date)||((RANK[a.place]??9)-(RANK[b.place]??9))||a.utc-b.utc);
}
const DATES=[["any","Any time"],["today","Today"],["week","This week"],["weekend","Weekend"],["30","Next 30 days"]];
