  const empty=()=>`<div class="sad empty"><div><span class="eyebrow" style="color:var(--accent)">Sidebar ad</span><h3>Your brand <em>here</em></h3><p>In view while people scroll ${h?esc(h.name)+"'s":"the"} events.</p></div><div class="foot"><span class="dim">300 × 250 · from ${money(SLOTS.side.durs[0][2])}</span><button class="btn btn-line btn-sm" type="button" data-book="side"${hub?` data-bcity="${hub}"`:""}>Book</button></div></div>`;
