  if(t.dataset.date){st.date=t.dataset.date;st.day=null;renderCity();return;}
  if(t.dataset.v){st.mode=t.dataset.v;renderCity();return;}
  if(t.dataset.day){st.day=t.dataset.day;st.mode="list";st.date="any";renderCity();document.getElementById("cq").scrollIntoView({behavior:"smooth",block:"center"});return;}
  if(t.dataset.mon){const [y,m]=st.month.split("-").map(Number);const d=new Date(Date.UTC(y,m-1+(+t.dataset.mon),1));st.month=d.toISOString().slice(0,7);renderCity();return;}
  if(t.dataset.host){st.q=t.dataset.host;renderCity();return;}
