async function handle(text){
  me(text);
  if(chat.state==="ask"){
    const urls=[...new Set(text.match(/https?:\/\/\S+/g)||[])];
    if(urls.length>1){
      const take=urls.slice(0,MAX_BATCH);chat.queue=take.slice(1);chat.idx=1;chat.total=take.length;
      await bot(`Got it — ${take.length} events. I'll take them one at a time, starting with the first.`+(urls.length>MAX_BATCH?` I can only do ${MAX_BATCH} at once, so send the rest after these.`:""),400);
      await resolveAndShowCard(take[0]);
    }else{
      chat.queue=[];chat.idx=1;chat.total=1;
      await resolveAndShowCard(urls[0]||null);
    }
  }else if(chat.state==="card"){await bot("Edit the card above, then tap <b>Looks right</b>.",350);}
  else{await bot("Want to add another? Tap + at the top to start over.",350);}
}
function tzList(){try{return Intl.supportedValuesOf("timeZone");}catch(e){return [...new Set([myTz,...HUBS.map(h=>h.tz)])].sort();}}
function showCard(){
  const d=chat.draft,c=document.createElement("div");c.className="ecard";c.id="ecard";
  c.innerHTML=`<h4>${d.title?esc(d.title):"Your <em>event</em>"}</h4>
  <label>Title<input id="eTitle2" value="${esc(d.title)}" placeholder="e.g. AI Founders Dinner"></label>
  <div class="row2"><label>Date<input id="eDate2" type="date" value="${esc(d.date)}" min="2026-10-19"></label><label>Last day, if longer<input id="eUntil2" type="date" value="${esc(d.until||"")}" min="${esc(d.date||"2026-10-19")}"></label></div>
  <label>Type<select id="eType2">${TYPES.map(t=>`<option${t===d.type?" selected":""}>${t}</option>`).join("")}</select></label>
  <div class="row2"><div class="catwrap"><span>Sectors (up to 5, optional)</span><div id="eSectors2"></div></div><div class="catwrap"><span>Also tag as (up to 3, optional)</span><div id="eCats2"></div></div></div>
  <div class="row2"><label>Starts<input id="eStart2" type="time" value="${esc(d.start)}"></label><label>Ends<input id="eEnd2" type="time" value="${esc(d.end)}"></label></div>
  <div class="row2"><label>City<select id="eHub2">${[...HUBS].sort((a,b)=>a.name.localeCompare(b.name)).map(h=>`<option value="${h.id}"${h.id===d.hub?" selected":""}>${h.name}</option>`).join("")}<option value="__new">My city isn't listed…</option></select></label><label>Venue<input id="eVenue2" value="${esc(d.venue)}" placeholder="Venue or neighborhood"></label></div>
  <div class="newcity" id="eNew2" hidden><div class="row2"><label>City name<input id="eNewName" placeholder="e.g. Porto"></label><label>Country<input id="eNewCountry" placeholder="e.g. Portugal"></label></div><label>Time zone<select id="eNewTz">${tzList().map(z=>`<option${z===myTz?" selected":""}>${z}</option>`).join("")}</select></label><span class="tzline">New cities open on the List once we accept the first event there.</span></div>
  <span class="tzline" id="eTz2"></span>
  <label>Host or organizer<input id="eHost2" value="${esc(d.host||"")}" placeholder="Who's hosting"></label>
  <label>Description<textarea id="eDesc2" rows="3" maxlength="600" placeholder="What it is, who it's for, who's speaking">${esc(d.desc||"")}</textarea></label>
  <label>Event link<input id="eLink2" type="url" value="${esc(d.link)}" placeholder="https://"></label>
  <div class="field"><span style="font-family:var(--f-label);font-size:10.5px;letter-spacing:.18em;text-transform:uppercase;color:var(--muted)">Cover image (optional)</span><div class="cover" data-cover="c"></div></div>
  <div class="row2"><label>Your name<input id="eName2" autocomplete="name" value="${esc(chat.who&&chat.who.name||"")}"></label><label>Your email *<input id="eEmail2" type="email" autocomplete="email" value="${esc(chat.who&&chat.who.email||"")}" placeholder="So we can confirm it"></label></div>
  <input id="eWeb2" tabindex="-1" autocomplete="off" aria-hidden="true" style="position:absolute;left:-9999px;width:1px;height:1px;opacity:0">
  <span class="err" id="eErr2" hidden></span>
  <button class="btn btn-primary" type="button" id="eOk2">Looks right</button>`;
  $("#dlog").append(c);COVER.c="";mountCover(c.querySelector('[data-cover="c"]'),"c","eCover2");scrollLog();
  const tz=()=>{const nw=$("#eHub2").value==="__new";$("#eNew2").hidden=!nw;const h=nw?{id:"x",name:$("#eNewName").value.trim()||"your city",tz:$("#eNewTz").value}:hubById($("#eHub2").value);$("#eTz2").textContent=`Times are in ${h.name} local time (${h.id==="virtual"?"ET":abbr(toUtc($("#eDate2").value||"2026-10-20","12:00",h.tz),h.tz)}).`;};
  tp("eSectors2",SECTORS,5,chat.draft.xsectors,"Type a sector");tp("eCats2",CAT_TYPES,3,chat.draft.xcats,"Type a category");
  {let touched=false;$("#eType2").onchange=()=>touched=true;$("#eTitle2").addEventListener("input",()=>{if(!touched)$("#eType2").value=inferType($("#eTitle2").value);});}
  tz();$("#eHub2").onchange=tz;$("#eNewTz").onchange=tz;$("#eNewName").oninput=tz;$("#eDate2").onchange=()=>{tz();const u=$("#eUntil2");u.min=$("#eDate2").value;if(u.value&&u.value<=$("#eDate2").value)u.value="";};$("#eTitle2").focus();
  $("#eOk2").onclick=confirmCard;
}
function confirmCard(){
  const v=id=>$(id).value.trim();const title=v("#eTitle2"),date=v("#eDate2");
  const nw=v("#eHub2")==="__new";const until=v("#eUntil2");const msg=!title?"Add a title.":!date?"Pick the date, in the event's local time.":until&&until<date?"The last day can't be before the first day.":until&&(Date.parse(until)-Date.parse(date))/864e5>60?"Multi-day events can run up to 60 days.":nw&&!v("#eNewName")?"Add the city name.":!okEmail(v("#eEmail2"))?"Add your email so we can confirm your event.":"";
  const er=$("#eErr2");er.textContent=msg;er.hidden=!msg;if(msg)return;
  let hubId=v("#eHub2"),newHub=null;
  if(nw){const nm=v("#eNewName");const ex=HUBS.find(h=>h.name.toLowerCase()===nm.toLowerCase());if(ex)hubId=ex.id;else{newHub=makeHub(nm,v("#eNewCountry"),v("#eNewTz"));HUBS.push(newHub);hubId=newHub.id;try{const nh=JSON.parse(localStorage.getItem("yl-newhubs")||"[]");nh.push(newHub);localStorage.setItem("yl-newhubs",JSON.stringify(nh));}catch(x){}}}
  chat.newHub=newHub;chat.who={name:v("#eName2"),email:v("#eEmail2"),web:$("#eWeb2").value};
  const d=Object.assign(chat.draft,{title,date,until:until>date?until:"",start:v("#eStart2"),end:v("#eEnd2"),hub:hubId,venue:v("#eVenue2"),type:v("#eType2"),xsectors:picked("eSectors2"),xcats:picked("eCats2"),host:v("#eHost2"),desc:v("#eDesc2"),link:/^https?:\/\//.test(v("#eLink2"))?v("#eLink2"):""});
  if(d.start&&!d.end){const [hh,mm]=d.start.split(":").map(Number);d.end=String(Math.min(23,hh+2)).padStart(2,"0")+":"+String(mm).padStart(2,"0");}
  $("#ecard").outerHTML=`<div class="esum">${esc(d.title)}</div>`;
  me("Looks right");chat.state="review";
  const st2=document.createElement("div");st2.className="status";st2.innerHTML=`<span class="spin"></span><span><b>${esc(d.title)}</b><small>Reviewing your event…</small></span>`;$("#dlog").append(st2);scrollLog();
  const hh=hubById(hubId);
  const sent=sendSubmission({title:d.title,hub:newHub?"":hubId,hubName:hh?hh.name:"",newCity:newHub?[newHub.name,newHub.country].filter(Boolean).join(", "):"",date:d.date,until:d.until,start:d.start,end:d.end,tz:newHub?newHub.tz:(hh?hh.tz:""),venue:d.venue,type:d.type,sector:(d.xsectors||[]).join(","),tags:(d.xcats||[]).join(","),host:d.host,link:d.link,desc:d.desc,placement:"free",name:chat.who.name,email:chat.who.email,website:chat.who.web,image:COVER.c||"",via:d.dup?"chat-update":"chat"});
  const cv=COVER.c;COVER.c="";
  setTimeout(async()=>{
    const res=await sent;
    let e=d.dup?EVENTS.find(x=>x.id===d.dup):null;
    if(e){Object.assign(e,{title:d.title,date:d.date,until:d.until,start:d.start||null,end:d.start?d.end:null,hub:d.hub,venue:d.venue,type:d.type,xsectors:d.xsectors||[],xcats:d.xcats||[],host:d.host||e.host,desc:d.desc||e.desc,link:d.link||e.link});if(cv)e.cover=cv;decorate(e);}
    else{e=decorate({id:"u"+Date.now(),title:d.title,hub:d.hub,date:d.date,until:d.until,start:d.start||null,end:d.start?d.end:null,type:d.type,xsectors:d.xsectors||[],xcats:d.xcats||[],host:d.host||"",tags:inferTags(d.title+" "+(d.desc||"")),aud:[],place:null,week:null,img:"ev"+(1+Math.floor(Math.random()*8)),venue:d.venue,link:d.link,desc:d.desc||"Submitted to the List.",cover:cv||"",mine:true});EVENTS.push(e);
      try{const s=JSON.parse(localStorage.getItem("yl-subs2")||"[]");const c={...e};delete c.utc;delete c.utcEnd;delete c.cover;s.push(c);localStorage.setItem("yl-subs2",JSON.stringify(s));}catch(x){}}
    const h=hubById(e.hub);
    st2.innerHTML=`<span class="done">✓</span><span><b>${esc(e.title)}</b><small>${res.ok?(res.live?"Live on the List":"Sent for review"):"Not sent yet"} · ${h.name} · ${dParts(e.date).wd} ${dParts(e.date).day} ${dParts(e.date).mon}</small></span>`;
    // A multi-link paste queues the other links in chat.queue (see handle()/resolveAndShowCard). Each one still
    // gets its own full result message below -- nothing is skipped on a failure -- we just don't stop at "done"
    // until the last one, and chain straight into the next link's card instead of waiting for the person to
    // tap + and paste again.
    const hasMore=chat.queue&&chat.queue.length>0;
    chat.state=hasMore?"card":"done";
    bot(res.ok?`<b>Received.</b> ${res.dup?"We already have this event, so nothing more to do.":res.live?"Your event is live on the List now.":`We review every event within a day, and it goes live on the List once approved. If we need anything, we'll email ${esc(chat.who.email)}.`} Some events also get picked for the weekly email.<br><br><button class="btn btn-sm btn-line" type="button" data-ev="${e.id}" id="seeMine">Preview your event</button>${res.dup?"":` <button class="btn btn-sm btn-primary" type="button" data-featev="${e.id}" data-who="1">★ Feature it from US$69</button><small style="display:block;margin-top:8px;color:var(--muted)">Featured events get a ★ badge, sit at the top of their day and get a star on the map until the event.</small>`}${hasMore?"":`<small style="display:block;margin-top:10px;color:var(--muted)">Want Yorkseed as co-host? <a href="https://yorkseed.co/event-partner-request.html" target="_blank" rel="noopener" style="color:var(--accent)">Request an event partnership →</a></small>`}`:`${res.msg?esc(res.msg)+" ":"We couldn't reach our server just now. "}Send it to the Yorkseed team by email instead:<br><br><a class="btn btn-sm btn-primary" href="${esc(mailYS("New event for The List: "+e.title,["Event: "+e.title,"City: "+h.name+(chat.newHub?" (new city, "+(chat.newHub.country||"")+")":""),"Date: "+e.date+(e.start?" "+e.start+(e.end?"–"+e.end:""):"")+" ("+h.tz+")","Venue: "+(e.venue||""),"Type: "+e.type,"Host: "+(e.host||""),"Link: "+(e.link||""),"","Description:",(e.desc&&e.desc!=="Submitted to the List.")?e.desc:"",d.dup?"(Update to an event already on the List)":""]))}" target="_blank" rel="noopener">Send to Yorkseed</a> <button class="btn btn-sm btn-line" type="button" data-ev="${e.id}" id="seeMine">Preview your event</button><br><small style="display:block;margin-top:8px;color:var(--muted)">Opens your email with the details filled in. Or email ${YS_INBOX}.</small>${hasMore?"":`<small style="display:block;margin-top:10px;color:var(--muted)">Want Yorkseed as co-host? <a href="https://yorkseed.co/event-partner-request.html" target="_blank" rel="noopener" style="color:var(--accent)">Request an event partnership →</a></small>`}`,600).then(bub=>{
      // scope to this bubble, not a global $("#seeMine") -- a batch of 2-3 events puts more than one
      // #seeMine button in the DOM at once, and querySelector would otherwise always grab the first one
      // in document order instead of the one that was just shown.
      const b=bub.querySelector("#seeMine");if(b&&!hasMore)b.addEventListener("click",closeChat);
      if(hasMore){chat.idx=(chat.idx||1)+1;const next=chat.queue.shift();bot(`Next up, event ${chat.idx} of ${chat.total}…`,450).then(()=>resolveAndShowCard(next));}
    });
    renderHome();if(st.view==="city")renderCity();
  },1500);
}
